import re,pathlib
hits={}
for p in pathlib.Path('.').rglob('*'):
    if p.is_file() and '.git' not in p.parts:
        try: t=p.read_text()
        except Exception: continue
        if 'legacy_fetch' in t:
            hits[str(p)]=[l for l in t.splitlines() if 'legacy_fetch' in l and not re.search(r'(api\.)?legacy_fetch\("https://example\.test/m\d+/\d+"(, timeout=9)?\)$', l.strip().removeprefix('return '))]
for k,v in sorted(hits.items()): print(k,v)

